let file = """{"version":3,"file":"systemStatsStore-DITxPBHR.js","names":[],"sources":["../../src/stores/systemStatsStore.ts"],"sourcesContent":["import { useAsyncState } from '@vueuse/core'\nimport { defineStore } from 'pinia'\n\nimport { isCloud, isDesktop } from '@/platform/distribution/types'\nimport type { SystemStats } from '@/platform/remote/comfyui/types'\nimport { api } from '@/scripts/api'\n\nexport const useSystemStatsStore = defineStore('systemStats', () => {\n  const fetchSystemStatsData = async () => {\n    try {\n      return await api.getSystemStats()\n    } catch (err) {\n      console.error('Error fetching system stats:', err)\n      throw err\n    }\n  }\n\n  const {\n    state: systemStats,\n    isLoading,\n    error,\n    isReady: isInitialized,\n    execute: refetchSystemStats\n  } = useAsyncState<SystemStats | null>(\n    fetchSystemStatsData,\n    null, // initial value\n    {\n      immediate: true\n    }\n  )\n\n  function getFormFactor(): string {\n    if (isCloud) {\n      return 'cloud'\n    }\n\n    if (!systemStats.value?.system.os) {\n      return 'other'\n    }\n\n    const os = systemStats.value.system.os.toLowerCase()\n\n    if (isDesktop) {\n      if (os.includes('windows')) {\n        return 'desktop-windows'\n      }\n      if (os.includes('darwin') || os.includes('mac')) {\n        return 'desktop-mac'\n      }\n    } else {\n      // Git/source installation\n      if (os.includes('windows')) {\n        return 'git-windows'\n      }\n      if (os.includes('darwin') || os.includes('mac')) {\n        return 'git-mac'\n      }\n      if (os.includes('linux')) {\n        return 'git-linux'\n      }\n    }\n\n    return 'other'\n  }\n\n  return {\n    systemStats,\n    isLoading,\n    error,\n    isInitialized,\n    refetchSystemStats,\n    getFormFactor\n  }\n})\n"],"mappings":"+KAOA,IAAa,EAAsB,EAAY,kBAAqB,CAClE,IAAM,qBAAuB,SAAY,CACvC,GAAI,CACF,OAAO,MAAM,EAAI,eAAe,CAClC,OAAS,EAAK,CAEZ,MADA,QAAQ,MAAM,+BAAgC,CAAG,EAC3C,CACR,CACF,EAEM